#requires -Version 7.0
$ErrorActionPreference = 'Stop'

$repositoryRoot = Split-Path (Split-Path $PSScriptRoot -Parent) -Parent
$inputPath = Join-Path $repositoryRoot 'Kotowari.Benchmarks/Data/test.json'
$expectedInputHash = 'DC87DD0FB85CB6F875AC336B70FEFC1E32BB1F284C8F6E011E0CB0256F9A354D'
$inputHash = (Get-FileHash -LiteralPath $inputPath -Algorithm SHA256).Hash
if ($inputHash -ne $expectedInputHash) {
    throw "Unexpected input SHA256: $inputHash"
}

$bytes = [IO.File]::ReadAllBytes($inputPath)
$jsonText = [Text.UTF8Encoding]::new($false, $true).GetString($bytes)
$document = [System.Text.Json.JsonDocument]::Parse([string]$jsonText)
$stack = [Collections.Generic.Stack[System.Text.Json.JsonElement]]::new()
$stack.Push($document.RootElement)
$counts = [ordered]@{
    Object = 0
    Array = 0
    Number = 0
    String = 0
    True = 0
    False = 0
    Null = 0
    ValueNodes = 0
    ObjectProperties = 0
}
$propertyNameLengths = [Collections.Generic.List[int]]::new()
$stringValueLengths = [Collections.Generic.List[int]]::new()
$numberRawTextLengths = [Collections.Generic.List[int]]::new()
$arrayChildCounts = [Collections.Generic.List[int]]::new()
$objectPropertyCounts = [Collections.Generic.List[int]]::new()

try {
    while ($stack.Count -gt 0) {
        $element = $stack.Pop()
        $counts.ValueNodes++
        switch ($element.ValueKind) {
            'Object' {
                $counts.Object++
                $properties = @($element.EnumerateObject())
                $objectPropertyCounts.Add($properties.Count)
                $counts.ObjectProperties += $properties.Count
                foreach ($property in $properties) {
                    $propertyNameLengths.Add($property.Name.Length)
                    $stack.Push($property.Value)
                }
            }
            'Array' {
                $counts.Array++
                $children = @($element.EnumerateArray())
                $arrayChildCounts.Add($children.Count)
                foreach ($child in $children) { $stack.Push($child) }
            }
            'Number' {
                $counts.Number++
                $numberRawTextLengths.Add($element.GetRawText().Length)
            }
            'String' {
                $counts.String++
                $stringValueLengths.Add($element.GetString().Length)
            }
            'True' { $counts.True++ }
            'False' { $counts.False++ }
            'Null' { $counts.Null++ }
        }
    }

    function Get-LengthSummary([Collections.Generic.List[int]] $lengths) {
        $sorted = @($lengths | Sort-Object)
        $histogram = [ordered]@{}
        foreach ($group in ($sorted | Group-Object)) {
            $histogram[[string]$group.Name] = $group.Count
        }
        $sum = 0L
        foreach ($length in $sorted) { $sum += $length }
        $p50 = if ($sorted.Count -gt 0) { $sorted[[int][Math]::Floor(($sorted.Count - 1) * 0.50)] } else { $null }
        $p95 = if ($sorted.Count -gt 0) { $sorted[[int][Math]::Floor(($sorted.Count - 1) * 0.95)] } else { $null }
        return [ordered]@{
            Count = $sorted.Count
            Total = $sum
            Min = if ($sorted.Count -gt 0) { $sorted[0] } else { $null }
            Median = $p50
            P95 = $p95
            Max = if ($sorted.Count -gt 0) { $sorted[-1] } else { $null }
            DistributionByLength = $histogram
        }
    }

    $record = [ordered]@{
        Input = [ordered]@{
            Path = 'Kotowari.Benchmarks/Data/test.json'
            Bytes = $bytes.Length
            SHA256 = $inputHash
            Parser = 'System.Text.Json.JsonDocument.Parse(string)'
            TextEncoding = 'UTF-8 strict; decoded string and property-name lengths are .NET UTF-16 code units'
        }
        Counts = $counts
        Lengths = [ordered]@{
            PropertyNames = Get-LengthSummary $propertyNameLengths
            StringValues = Get-LengthSummary $stringValueLengths
            NumberRawText = Get-LengthSummary $numberRawTextLengths
        }
        ContainerSizes = [ordered]@{
            ArrayChildCount = Get-LengthSummary $arrayChildCounts
            ObjectPropertyCount = Get-LengthSummary $objectPropertyCounts
        }
        Semantics = @(
            'ValueNodes counts JSON values including containers and scalars; object property names are not value nodes.',
            'PropertyNames and StringValues are separate populations; decoded lengths use .NET string.Length (UTF-16 code units).',
            'NumberRawText lengths count the exact JSON token text returned by JsonElement.GetRawText().',
            'This is input structure accounting only; no CPU or throughput measurement.'
        )
    }
    ConvertTo-Json -InputObject $record -Depth 12
}
finally {
    $document.Dispose()
}
